jQuery(document).ready(function ($) {
  $("#la-redirect-modal").modal({
    backdrop: "static", //remove ability to close modal with click
    keyboard: true, //remove option to close with keyboard
    show: false, //Display loader!
  });

  // Mouse Button 1: click
  // Mouse Button 2: contextmenu
  // Middle Mouse Button: auxclick

  // $(".la-link-class").click

(function (event) {
  $(".la-link-class").on("click auxclick contextmenu", function (event) {
    event.preventDefault(); // prevent default behaviour of link click

    if (event.which === 3) {
      return false;
    }

    // Google Event
    var la_storename = $(".la-offer-store a").text();
    var la_posturl = window.location.pathname;
    la_posturl = la_posturl.split("?")[0];
    la_posturl = la_posturl.split("#")[0];
    la_posturl = decodeURIComponent(la_posturl);

    gtag("event", "Affiliate", {
      event_category: la_storename,
      event_label: la_posturl,
      value: "",
    });
    // --------

    var $this = $(this),
      selectedURL = $this.attr("data-url");

    const loadingModal = $("#la-redirect-modal");
    // loadingModal.modal("show");

    var windowReference = window.open();

    // Post to The Wordpress URL
    $.ajax({
      url: ajax_object.ajaxurl,
      type: "POST",
      data: {
        action: "affiliate_link_action", // This is the PHP function to call - note it must be hooked to AJAX
        la_url: selectedURL,
      },
      success: function (data) {
        // loadingModal.modal("hide");
        var url = data.trim();
        windowReference.location = url;
      },
    });

    return false;
  });

  function openInNewTab(url) {
    var win = window.open(url, "_blank");
    win.focus();
  }
});
